use vstd::prelude::*;

verus! {

/// Spec-level reverse of a sequence.
spec fn rev_seq(s: Seq<i32>) -> Seq<i32> {
    s.reverse()
}

fn reverse(a: &Vec<i32>) -> (result: Vec<i32>)
    ensures
        result@ == rev_seq(a@),
        result@.len() == a@.len(),
{
    let n = a.len();
    let mut result = Vec::with_capacity(n);

    for i in (0..n).rev()
        invariant
            // `i` is always a valid index for `a` while in the loop body.
            i < n,
            // The result is the reverse of the suffix already traversed:
            // indices (i+1 .. n) have been pushed in decreasing order.
            result@ == rev_seq(a@.subrange((i + 1) as int, n as int)),
        decreases i,
    {
        result.push(a[i]);
        // Help the prover connect the updated `result@` to the updated subrange.
        assert(a@.subrange(i as int, n as int)
            == seq![a@[i as int]] + a@.subrange((i + 1) as int, n as int));
        assert(
            rev_seq(a@.subrange(i as int, n as int))
            == rev_seq(a@.subrange((i + 1) as int, n as int)) + seq![a@[i as int]]
        );
        assert(result@ == rev_seq(a@.subrange(i as int, n as int)));
    }

    // After the loop, all indices (0..n) have been pushed, so we have the full reverse.
    assert(a@.subrange(0, n as int) == a@);
    assert(result@ == rev_seq(a@.subrange(0, n as int)));
    result
}

} // verus!

